        if j == len(pattern): return i == len(text)
        first = i < len(text) and pattern[j] in ('.',text[i])
        if j+1 < len(pattern) and pattern[j+1] == '*':
            return match(i,j+2) or (first and match(i+1,j))
        return first and match(i+1,j+1)
    return match(0,0)

def glob_match(text, pattern):
    previous = [True]+[False]*len(text)
    for token in pattern:
        current = [previous[0] and token == '*']+[False]*len(text)
        for i,char in enumerate(text,1):
            current[i] = (previous[i] or current[i-1]) if token == '*' else (previous[i-1] and token in ('?',char))
        previous = current
    return previous[-1]

def longest_valid(text):
    stack = [-1]; best = 0
    for i,char in enumerate(text):
        if char == '(': stack.append(i)
        else:
            stack.pop()
            if not stack: stack.append(i)
            else: best = max(best,i-stack[-1])
    return best

def bridges(n, edges):
    graph = [[] for _ in range(n)]
    for a,b in edges: graph[a].append(b); graph[b].append(a)
    entered = [-1]*n; low = [0]*n; result = []; clock = 0
    def visit(node,parent):
        nonlocal clock
        entered[node] = low[node] = clock; clock += 1
        for other in graph[node]:
            if other == parent: continue
            if entered[other] < 0:
                visit(other,node); low[node] = min(low[node],low[other])
                if low[other] > entered[node]: result.append(sorted([node,other]))
            else: low[node] = min(low[node],entered[other])
    for node in range(n):
        if entered[node] < 0: visit(node,-1)
    return sorted(result)

def maximum_flow(capacity, source, sink):
    from collections import deque
    residual = [row[:] for row in capacity]; n = len(residual); total = 0
    while True:
        parent = [-1]*n; parent[source] = source; queue = deque([source])
        while queue and parent[sink] < 0:
            node = queue.popleft()
            for other,value in enumerate(residual[node]):
                if value > 0 and parent[other] < 0: parent[other] = node; queue.append(other)
        if parent[sink] < 0: return total
        amount = float('inf'); node = sink
        while node != source: amount = min(amount,residual[parent[node]][node]); node = parent[node]
        node = sink
        while node != source:
            before = parent[node]; residual[before][node] -= amount; residual[node][before] += amount; node = before
        total += amount

