def solve_sudoku(board):
    grid = [row[:] for row in board]
    def solve():
        for r in range(4):
            for c in range(4):
                if grid[r][c] == 0:
                    used = set(grid[r]) | {grid[i][c] for i in range(4)} | {grid[i][j] for i in range(r//2*2,r//2*2+2) for j in range(c//2*2,c//2*2+2)}
                    for value in range(1,5):
                        if value not in used:
                            grid[r][c] = value
                            if solve(): return True
                    grid[r][c] = 0
                    return False
        return True
    return grid if solve() else None

def queens_count(n):
    columns,down,up = set(),set(),set()
    def visit(row):
        if row == n: return 1
        total = 0
        for col in range(n):
            if col in columns or row-col in down or row+col in up: continue
            columns.add(col); down.add(row-col); up.add(row+col)
            total += visit(row+1)
            columns.remove(col); down.remove(row-col); up.remove(row+col)
        return total
    return visit(0)

def board_words(board, words):
    if not board or not board[0]: return []
    trie = {}; found = set(); rows,cols = len(board),len(board[0])
    for word in words:
        if not word: continue
        node = trie
        for char in word: node = node.setdefault(char,{})
        node[''] = word
    def visit(r,c,node,used):
        if not (0<=r<rows and 0<=c<cols) or (r,c) in used or board[r][c] not in node: return
        node = node[board[r][c]]
        if '' in node: found.add(node[''])
        used.add((r,c))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): visit(r+dr,c+dc,node,used)
        used.remove((r,c))
    for r in range(rows):
        for c in range(cols): visit(r,c,trie,set())
    return sorted(found)

def visit_all(graph):
    from collections import deque
    n = len(graph)
    if not n: return 0
    queue = deque((i,1<<i,0) for i in range(n)); seen = {(i,1<<i) for i in range(n)}
    while queue:
        node,mask,distance = queue.popleft()
        if mask == (1<<n)-1: return distance
        for other in graph[node]:
            state = (other,mask | (1<<other))
            if state not in seen: seen.add(state); queue.append((*state,distance+1))
    return -1

def inversions(items):
    def sort(values):
        if len(values) < 2: return list(values),0
        middle = len(values)//2; left,a = sort(values[:middle]); right,b = sort(values[middle:])
        i = j = 0; result = []; count = a+b
        while i < len(left) and j < len(right):
            if left[i] <= right[j]: result.append(left[i]); i += 1
            else: result.append(right[j]); j += 1; count += len(left)-i
        return result+left[i:]+right[j:],count
    return sort(items)[1]
